-- Name: end_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.end_session(p_session_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.sessions
    set ended_at = now(),
        duration_seconds = extract(epoch from (now() - started_at))::int
  where id = p_session_id
    and user_id = auth.uid();
end;
$$;


--
-- Name: get_or_create_referral_code(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_or_create_referral_code(p_user_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_code TEXT;
BEGIN
  SELECT code INTO v_code FROM referral_codes WHERE user_id = p_user_id;
  IF v_code IS NOT NULL THEN RETURN v_code; END IF;

  v_code := substr(md5(random()::text || p_user_id::text || now()::text), 1, 8);
  INSERT INTO referral_codes (user_id, code) VALUES (p_user_id, v_code)
  ON CONFLICT (user_id) DO NOTHING;

  SELECT code INTO v_code FROM referral_codes WHERE user_id = p_user_id;
  RETURN v_code;
END;
$$;


--
-- Name: get_referral_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_referral_stats(p_user_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_code TEXT;
  v_clicks INT;
  v_click_credits INT;
  v_signups INT;
  v_activated INT;
  v_signup_credits INT;
  v_bonus INT;
BEGIN
  SELECT code INTO v_code FROM referral_codes WHERE user_id = p_user_id;

  SELECT COUNT(*) INTO v_clicks FROM referral_clicks
    WHERE referrer_id = p_user_id AND credited = true;
  v_click_credits := LEAST(v_clicks * 5, 50);

  SELECT COUNT(*) INTO v_signups FROM referral_signups
    WHERE referrer_id = p_user_id;
  SELECT COUNT(*) INTO v_activated FROM referral_signups
    WHERE referrer_id = p_user_id AND activated = true AND referrer_credited = true;
  v_signup_credits := v_activated * 100;

  SELECT COALESCE(balance, 0) INTO v_bonus FROM bonus_credits WHERE user_id = p_user_id;

  RETURN json_build_object(
    'code', v_code,
    'clicks', v_clicks,
    'click_credits', v_click_credits,
    'click_credits_cap', 50,
    'signups', v_signups,
    'activated', v_activated,
    'signup_credits', v_signup_credits,
    'bonus_balance', COALESCE(v_bonus, 0),
    'total_earned', v_click_credits + v_signup_credits
  );
END;
$$;


--
-- Name: get_user_credits(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_credits(p_user_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tier         text := 'free';
  v_period_start timestamptz;
  v_period_end   timestamptz;
  v_cancel       boolean := false;
  v_pack_balance int := 0;
  v_pack_bought  int := 0;
  v_bonus        int := 0;
  v_credits_used int;
  v_monthly      int;
BEGIN
  SELECT tier, current_period_start, current_period_end, cancel_at_period_end,
         COALESCE(pack_credits_balance, 0), COALESCE(pack_credits_purchased, 0)
    INTO v_tier, v_period_start, v_period_end, v_cancel, v_pack_balance, v_pack_bought
    FROM public.subscriptions
   WHERE user_id = p_user_id AND status IN ('active', 'trialing')
   ORDER BY created_at DESC
   LIMIT 1;

  IF v_tier IS NULL THEN v_tier := 'free'; END IF;

  IF v_tier = 'free' THEN
    SELECT first_seen_at INTO v_period_start FROM public.profiles WHERE id = p_user_id;
    v_period_start := COALESCE(v_period_start, '1970-01-01'::timestamptz);
    v_period_end := NULL;
  ELSIF v_period_start IS NULL THEN
    v_period_start := date_trunc('month', now());
  END IF;

  SELECT COALESCE(balance, 0) INTO v_bonus FROM public.bonus_credits WHERE user_id = p_user_id;

  SELECT COALESCE(SUM(credits_cost), 0) INTO v_credits_used
    FROM public.usage_logs
   WHERE user_id = p_user_id AND created_at >= v_period_start;

  -- Cap monthly usage at the allowance; over-monthly overflow is accounted in the wallet.
  v_monthly := tier_monthly_credits(v_tier);
  IF v_monthly IS NOT NULL AND v_credits_used > v_monthly THEN
    v_credits_used := v_monthly;
  END IF;

  RETURN json_build_object(
    'tier', v_tier,
    'period_start', v_period_start,
    'period_end', v_period_end,
    'cancel_at_period_end', v_cancel,
    'credits_used', v_credits_used,
    'pack_credits', v_pack_balance,
    'pack_purchased', v_pack_bought,
    'bonus_credits', COALESCE(v_bonus, 0)
  );
END;
$$;


--
-- Name: get_user_tier_and_usage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_tier_and_usage(p_user_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tier text := 'free';
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_cancel boolean := false;
  v_text_count int;
  v_tts_count int;
  v_image_count int;
  v_video_count int;
  v_chat_count int;
begin
  select tier, current_period_start, current_period_end, cancel_at_period_end
    into v_tier, v_period_start, v_period_end, v_cancel
  from subscriptions
  where user_id = p_user_id and status in ('active', 'trialing')
  order by created_at desc limit 1;

  if v_tier is null then v_tier := 'free'; end if;
  if v_period_start is null then v_period_start := date_trunc('month', now()); end if;

  select
    coalesce(sum(case when action like 'text:%' or action in (
      'analyzeBookStructure','extractChapterText','extractConcepts',
      'extractDictionary','podcastScript','videoPrompt'
    ) then 1 else 0 end), 0),
    coalesce(sum(case when action in ('tts','podcastAudio') then 1 else 0 end), 0),
    coalesce(sum(case when action = 'generateImage' then 1 else 0 end), 0),
    coalesce(sum(case when action in ('videoVeo','videoSeedance') then 1 else 0 end), 0),
    coalesce(sum(case when action = 'chat' then 1 else 0 end), 0)
  into v_text_count, v_tts_count, v_image_count, v_video_count, v_chat_count
  from usage_logs
  where user_id = p_user_id and created_at >= v_period_start;

  return json_build_object(
    'tier', v_tier,
    'period_start', v_period_start,
    'period_end', v_period_end,
    'cancel_at_period_end', v_cancel,
    'text_used', v_text_count,
    'tts_used', v_tts_count,
    'image_used', v_image_count,
    'video_used', v_video_count,
    'chat_used', v_chat_count
  );
end;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.profiles (id, email, display_name, avatar_url)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'),
    new.raw_user_meta_data ->> 'avatar_url'
  );
  return new;
end;
$$;


--
-- Name: increment_generation_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_generation_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status = 'success' then
    update public.profiles
      set total_generations = total_generations + 1
    where id = new.user_id;
  end if;
  return new;
end;
$$;


--
-- Name: normalize_email(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_email(e text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN e IS NULL OR position('@' in e) = 0 THEN NULL
    ELSE (
      WITH p AS (
        SELECT split_part(lower(trim(e)), '@', 1) AS loc,
               split_part(lower(trim(e)), '@', 2) AS dom
      )
      SELECT CASE
        WHEN dom IN ('gmail.com', 'googlemail.com')
          THEN regexp_replace(split_part(loc, '+', 1), '\.', '', 'g') || '@gmail.com'
        ELSE split_part(loc, '+', 1) || '@' || dom
      END
      FROM p
    )
  END;
$$;


