--
-- Name: start_session(text, text, text, integer, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_session(p_device_type text DEFAULT NULL::text, p_os text DEFAULT NULL::text, p_browser text DEFAULT NULL::text, p_screen_width integer DEFAULT NULL::integer, p_screen_height integer DEFAULT NULL::integer, p_referrer text DEFAULT NULL::text, p_is_pwa boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session_id uuid;
begin
  insert into public.sessions (user_id, device_type, os, browser, screen_width, screen_height, referrer, is_pwa)
  values (auth.uid(), p_device_type, p_os, p_browser, p_screen_width, p_screen_height, p_referrer, p_is_pwa)
  returning id into v_session_id;

  update public.profiles set last_active_at = now() where id = auth.uid();

  return v_session_id;
end;
$$;


--
-- Name: tier_monthly_credits(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tier_monthly_credits(p_tier text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE p_tier
           WHEN 'pro' THEN 1000
           ELSE 100          -- free and any legacy/unknown tier: metered at the free allowance
         END;
$$;


--
-- Name: track_event(uuid, text, text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.track_event(p_session_id uuid, p_event_type text, p_event_action text, p_book_id text DEFAULT NULL::text, p_chapter_index integer DEFAULT NULL::integer, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_event_id uuid;
begin
  insert into public.events (user_id, session_id, event_type, event_action, book_id, chapter_index, metadata)
  values (auth.uid(), p_session_id, p_event_type, p_event_action, p_book_id, p_chapter_index, p_metadata)
  returning id into v_event_id;

  update public.profiles set last_active_at = now() where id = auth.uid();

  return v_event_id;
end;
$$;


--
-- Name: track_generation(text, integer, text, text, text, integer, integer, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
