CREATE FUNCTION public.track_generation(p_book_id text, p_chapter_index integer, p_module text, p_provider text, p_model text, p_input_chars integer, p_output_duration_ms integer DEFAULT NULL::integer, p_estimated_cost numeric DEFAULT NULL::numeric, p_status text DEFAULT 'success'::text, p_error_message text DEFAULT NULL::text) RETURNS uuid
