--
-- Name: trg_referral_engagement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_referral_engagement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Never let referral logic break usage logging: swallow any error.
  BEGIN
    PERFORM award_referral_on_engagement(NEW.user_id);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  RETURN NEW;
END;
$$;


