--
-- Name: v_daily_active_users; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_daily_active_users AS
 SELECT (date_trunc('day'::text, created_at))::date AS day,
    count(DISTINCT user_id) AS dau
   FROM public.events
  WHERE (user_id IS NOT NULL)
  GROUP BY ((date_trunc('day'::text, created_at))::date)
  ORDER BY ((date_trunc('day'::text, created_at))::date) DESC;


--
-- Name: v_daily_events_by_module; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_daily_events_by_module AS
 SELECT (date_trunc('day'::text, created_at))::date AS day,
    event_type,
    event_action,
    count(*) AS event_count,
    count(DISTINCT user_id) AS unique_users
   FROM public.events
  GROUP BY ((date_trunc('day'::text, created_at))::date), event_type, event_action
  ORDER BY ((date_trunc('day'::text, created_at))::date) DESC, (count(*)) DESC;


--
-- Name: v_feature_adoption; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_feature_adoption AS
 SELECT user_id,
    array_agg(DISTINCT module) AS modules_used,
    count(DISTINCT module) AS module_count,
    min(created_at) AS first_generation,
    max(created_at) AS last_generation
   FROM public.generations
  WHERE (status = 'success'::text)
  GROUP BY user_id;


--
-- Name: v_generation_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_generation_stats AS
 SELECT module,
    status,
    count(*) AS total,
    avg(input_chars) AS avg_input_chars,
    avg(output_duration_ms) AS avg_output_ms,
    sum(estimated_cost_usd) AS total_cost_usd
   FROM public.generations
  GROUP BY module, status
  ORDER BY (count(*)) DESC;


--
-- Name: v_user_engagement; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_user_engagement AS
 SELECT p.id AS user_id,
    p.email,
    p.first_seen_at,
    p.last_active_at,
    p.total_books_uploaded,
    p.total_generations,
    count(DISTINCT s.id) AS total_sessions,
    COALESCE(avg(s.duration_seconds), (0)::numeric) AS avg_session_duration,
    count(DISTINCT e.id) AS total_events,
    max(e.created_at) AS last_event_at
   FROM ((public.profiles p
     LEFT JOIN public.sessions s ON ((s.user_id = p.id)))
     LEFT JOIN public.events e ON ((e.user_id = p.id)))
  GROUP BY p.id, p.email, p.first_seen_at, p.last_active_at, p.total_books_uploaded, p.total_generations;


--
-- Name: v_user_funnel; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_user_funnel AS
 SELECT id AS user_id,
    first_seen_at AS signed_up_at,
    ( SELECT min(to_timestamp((((ub.upload_date)::numeric / 1000.0))::double precision)) AS min
           FROM public.user_books ub
          WHERE (ub.user_id = p.id)) AS first_upload_at,
    ( SELECT min(g.created_at) AS min
           FROM public.generations g
          WHERE ((g.user_id = p.id) AND (g.status = 'success'::text))) AS first_generation_at,
    ( SELECT min(e.created_at) AS min
           FROM public.events e
          WHERE ((e.user_id = p.id) AND (e.event_type = 'share'::text))) AS first_share_at
   FROM public.profiles p;


